import jwt
import json
import os
import hashlib
from flask import Flask, request, jsonify
from functools import wraps

app = Flask(__name__)

# RSA public key used to verify device messages
RSA_PUBLIC_KEY = open('/etc/iot-gateway/device_signing_key.pub').read()

# Feature flags client
class FeatureFlagClient:
    def __init__(self):
        self._sdk_key = os.environ.get('SPLIT_SDK_KEY', '')
        self._cache = {}

    def get_treatment(self, flag_name, entity_id='default'):
        """Fetch treatment from Split.io SDK with local cache"""
        import splitio
        if not hasattr(self, '_factory'):
            config = splitio.Config(sdk_key=self._sdk_key)
            self._factory = splitio.get_factory(config)
            self._factory.block_until_ready(5)
        client = self._factory.client()
        return client.get_treatment(entity_id, flag_name)

flag_client = FeatureFlagClient()

def verify_device_token(token):
    """Verify JWT from IoT device. Supports RS256 and legacy HS256 path."""

    # Check if legacy symmetric verification is enabled
    legacy_mode = flag_client.get_treatment('iot_legacy_hmac_verification')

    header = jwt.get_unverified_header(token)

    if legacy_mode == 'on':
        # Legacy path: accept both RS256 and HS256
        # This allows algorithm confusion - attacker can sign with public key as HMAC secret
        if header.get('alg') == 'HS256':
            payload = jwt.decode(
                token,
                RSA_PUBLIC_KEY,
                algorithms=['HS256', 'RS256']
            )
        else:
            payload = jwt.decode(
                token,
                RSA_PUBLIC_KEY,
                algorithms=['RS256']
            )
    else:
        # Secure path: only RS256 accepted, algorithm from header is ignored
        payload = jwt.decode(
            token,
            RSA_PUBLIC_KEY,
            algorithms=['RS256']
        )

    return payload

def require_device_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing token'}), 401

        token = auth_header[7:]
        try:
            payload = verify_device_token(token)
            request.device_id = payload.get('device_id')
            request.device_claims = payload
        except jwt.InvalidTokenError as e:
            return jsonify({'error': f'Invalid token: {str(e)}'}), 401

        return f(*args, **kwargs)
    return decorated

@app.route('/api/v1/telemetry', methods=['POST'])
@require_device_auth
def ingest_telemetry():
    """Receive telemetry data from authenticated IoT devices"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'No data'}), 400

    # Process telemetry
    device_id = request.device_id
    readings = data.get('readings', [])

    # Store readings (simplified)
    stored = []
    for reading in readings:
        record = {
            'device_id': device_id,
            'sensor': reading.get('sensor'),
            'value': reading.get('value'),
            'timestamp': reading.get('ts')
        }
        stored.append(record)

    return jsonify({'status': 'ok', 'ingested': len(stored)}), 200

@app.route('/api/v1/command', methods=['POST'])
@require_device_auth
def send_command():
    """Send command to device - requires admin claim"""
    if not request.device_claims.get('admin'):
        return jsonify({'error': 'Insufficient privileges'}), 403

    command = request.get_json()
    # Execute device command
    return jsonify({'status': 'command_queued', 'command_id': hashlib.md5(json.dumps(command).encode()).hexdigest()}), 202

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8443)
